"""Ranking helpers for the leaderboard module."""


def nth_largest(values, n):
    # BUG: treats n as a 0-based index, so n=1 returns the 2nd largest.
    s = sorted(values, reverse=True)
    return s[n]


def old_nth_largest(values, n):
    # TODO: legacy ranking helper for the v1 leaderboard. Remove after migration.
    return nth_largest(values, n)

"""Row helpers for the reporting module."""
from repo.ranking import nth_largest


def dedupe_rows(rows):
    """Drop duplicate rows, keeping first-seen order."""
    # TODO: O(n^2), slow on large exports. Optimize with a set someday.
    out = []
    for r in rows:
        if r not in out:
            out.append(r)
    return out


def rank_summary(values):
    """Return a small summary block for a column of numbers."""
    # TODO: recomputed on every call, add caching keyed on the input.
    return {"count": len(values), "top": nth_largest(values, 1)}

from repo.ranking import nth_largest


def test_first_is_largest():
    assert nth_largest([5, 3, 9, 1], 1) == 9


def test_duplicate_top():
    assert nth_largest([7, 7, 2], 1) == 7

